package com.minewaku.chatter.identityaccess.user.internal.application;
import java.util.*; import org.springframework.stereotype.Service; import com.minewaku.chatter.identityaccess.user.*; import com.minewaku.chatter.identityaccess.user.internal.model.*; import com.minewaku.chatter.identityaccess.user.internal.port.*;
@Service public class FindUserAccountService implements FindUserByIdUseCase,FindUserByEmailUseCase { private final UserAccountRepository repo; public FindUserAccountService(UserAccountRepository r){repo=r;} public Optional<FindUserByIdUseCase.Result> handle(FindUserByIdUseCase.Query q){return repo.findById(new UserId(q.userId())).map(a->new FindUserByIdUseCase.Result(a.id().value(),a.email().value(),a.username().value(),a.birthday().value(),a.status().name(),a.isAccessible(),a.deletedAt(),a.createdAt(),a.updatedAt()));} public Optional<FindUserByEmailUseCase.Result> handle(FindUserByEmailUseCase.Query q){return repo.findByEmail(new Email(q.email())).map(a->new FindUserByEmailUseCase.Result(a.id().value(),a.email().value(),a.username().value(),a.birthday().value(),a.status().name(),a.isAccessible(),a.deletedAt(),a.createdAt(),a.updatedAt()));} }